func TestToolBudgetProducesFinalAnswerInsteadOfFatalError(t *testing.T) {
	fs := &fakeSession{docs: []domain.Document{{Title: "MCP", URL: "https://example.com", Text: "MCP connects tools."}}}
	llm := &budgetLLM{}
	out, err := New(Config{Timeout: 90 * time.Second, MaxToolCalls: 2, MaxToolRounds: 6}, llm, fakeConnector{fs}).Ask(context.Background(), "keep searching")
	if err != nil {
		t.Fatal(err)
	}
	if out.Content != "partial final answer" || fs.calls[knowledge.SearchTool] != 2 {
		t.Fatalf("content=%q calls=%d", out.Content, fs.calls[knowledge.SearchTool])
	}
	found := false
	for _, event := range out.Trace {
		if event.Stage == "agent/tool_budget" && event.ToolCallID == "budget-3" {
			found = true
		}
	}
	if !found {
		t.Fatal("tool budget event missing from trace")
	}
}

func TestDocumentTextLimitPreservesSourcePrefix(t *testing.T) {
	long := strings.Repeat("A factual sentence. ", 300)
	limited := limitDocumentText(long)
	if len([]rune(limited)) > maxDocumentRunes {
		t.Fatalf("limited text has %d runes", len([]rune(limited)))
	}
	if !strings.HasPrefix(long, limited) {
		t.Fatal("limited text is not an exact source prefix")
	}
	if !strings.HasSuffix(limited, ".") {
		t.Fatalf("expected sentence boundary, got %q", limited[len(limited)-20:])
	}
	withoutBoundary := strings.Repeat("x", maxDocumentRunes+100)
	if got := limitDocumentText(withoutBoundary); len([]rune(got)) != maxDocumentRunes || !strings.HasPrefix(withoutBoundary, got) {
		t.Fatal("fallback prefix limit failed")
	}
}

func Summarize(input domain.SummarizeInput) (domain.SummarizeOutput, error) {
	input.Query = cleanSpace(input.Query)
	if input.Query == "" || len([]rune(input.Query)) > 300 {
		return domain.SummarizeOutput{}, errors.New("query must contain 1 to 300 characters")
	}
	if input.MaxSentences < 1 || input.MaxSentences > 10 {
		return domain.SummarizeOutput{}, errors.New("max_sentences must be between 1 and 10")
	}
	if len(input.Documents) > 5 {
		return domain.SummarizeOutput{}, errors.New("documents must contain at most 5 items")
	}
	terms := meaningfulWords(input.Query)
	seen := map[string]bool{}
	all := make([]rankedSentence, 0)
	sources := make([]domain.Source, 0, len(input.Documents))
	seenSources := map[string]bool{}
	order := 0
	for _, document := range input.Documents {
		document.Title, document.URL, document.Text = cleanSpace(document.Title), strings.TrimSpace(document.URL), cleanSpace(document.Text)
		if document.URL != "" && !seenSources[document.URL] {
			sources = append(sources, domain.Source{Title: document.Title, URL: document.URL})
			seenSources[document.URL] = true
		}
		for _, match := range splitSentences(document.Text) {
			sentence := cleanSpace(match)
			key := strings.ToLower(strings.Trim(sentence, " .!?…"))
			if key == "" || seen[key] {
				continue
			}
			seen[key] = true
			words := meaningfulWords(sentence)
			score := len(words)
			for term := range terms {
				if words[term] {
					score += 12
				}
			}
			if len([]rune(sentence)) >= 45 && len([]rune(sentence)) <= 260 {
				score += 4
			}
			all = append(all, rankedSentence{text: sentence, order: order, score: score})
			order++
		}
	}
	warning := ""
	if len(all) == 0 {
		warning = "Недостаточно данных для составления сводки."
		return domain.SummarizeOutput{OK: true, Query: input.Query, Sources: sources, InputDocuments: len(input.Documents), Warning: warning}, nil
	}
	ranked := append([]rankedSentence(nil), all...)
	sort.SliceStable(ranked, func(i, j int) bool {
		if ranked[i].score == ranked[j].score {
			return ranked[i].order < ranked[j].order
		}
		return ranked[i].score > ranked[j].score
	})
	count := input.MaxSentences
	if len(ranked) < count {
		count = len(ranked)
		warning = "Доступно меньше информативных предложений, чем запрошено."
	}
	chosen := append([]rankedSentence(nil), ranked[:count]...)
	sort.Slice(chosen, func(i, j int) bool { return chosen[i].order < chosen[j].order })
	parts := make([]string, len(chosen))
	for i := range chosen {
		parts[i] = chosen[i].text
	}
	return domain.SummarizeOutput{OK: true, Query: input.Query, Summary: strings.Join(parts, " "), Sources: sources, InputDocuments: len(input.Documents), SentenceCount: len(chosen), Warning: warning}, nil
}

