func TestAggregationForZeroOneAndSeveralSnapshots(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 27, 10, 0, 0, 0, time.UTC)
	s, _ := openTestStore(t)
	schedule := createSchedule(t, s, now, nil)
	empty, err := s.Summary(ctx, schedule.ID)
	if err != nil || !empty.InsufficientData || empty.CurrentRate != "" {
		t.Fatalf("empty=%+v %v", empty, err)
	}
	run1, _ := s.ClaimDue(ctx, schedule.ID, now)
	if err := s.CompleteSuccess(ctx, *run1, snapshot("0.8000", "2026-09-26", now), now.Add(time.Second)); err != nil {
		t.Fatal(err)
	}
	one, err := s.Summary(ctx, schedule.ID)
	if err != nil || !one.InsufficientData || one.AbsoluteChange != "0" {
		t.Fatalf("one=%+v %v", one, err)
	}
	run2, _ := s.ClaimDue(ctx, schedule.ID, now.Add(time.Minute))
	_ = s.CompleteFailure(ctx, *run2, errors.New("upstream unavailable"), now.Add(time.Minute+time.Second))
	run3, _ := s.ClaimDue(ctx, schedule.ID, now.Add(2*time.Minute))
	_ = s.CompleteSuccess(ctx, *run3, snapshot("1.0000", "2026-09-27", now.Add(2*time.Minute)), now.Add(2*time.Minute+time.Second))
	many, err := s.Summary(ctx, schedule.ID)
	if err != nil {
		t.Fatal(err)
	}
	if many.CurrentRate != "1.0000" || many.FirstRate != "0.8000" || many.AbsoluteChange != "0.2" || many.PercentChange != "25" || many.MinimumRate != "0.8" || many.MaximumRate != "1" {
		t.Fatalf("summary=%+v", many)
	}
	if many.Schedule.RunCount != 3 || many.Schedule.SuccessCount != 2 || many.Schedule.ErrorCount != 1 || many.Schedule.SnapshotCount != 2 {
		t.Fatalf("counts=%+v", many.Schedule)
	}
}

func TestAgentModelSelectedPipelineAndExactTransfer(t *testing.T) {
	a, llm, dir := testPipeline(t, false)
	result, err := a.Ask(context.Background(), "Найди MCP, сделай сводку и сохрани.")
	if err != nil {
		t.Fatal(err)
	}
	if llm.step != 4 || result.Content == "" {
		t.Fatalf("incomplete loop: step=%d response=%+v", llm.step, result)
	}
	var order, ids []string
	for _, event := range result.Trace {
		if event.Stage == "model/tool_call" {
			order = append(order, event.Tool)
			ids = append(ids, event.ToolCallID)
		}
	}
	if !reflect.DeepEqual(order, []string{pipeline.SearchToolName, pipeline.SummarizeToolName, pipeline.SaveToolName}) {
		t.Fatalf("order=%v", order)
	}
	if !reflect.DeepEqual(ids, []string{"call-search", "call-summary", "call-save"}) {
		t.Fatalf("ids=%v", ids)
	}
	path := filepath.Join(dir, "mcp-summary.md")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	hash := fmt.Sprintf("%x", sha256.Sum256(data))
	var saved pipeline.SaveOutput
	for _, event := range result.Trace {
		if event.Stage == "mcp/tools/call" && event.Tool == pipeline.SaveToolName {
			encoded, _ := json.Marshal(event.Result)
			if err := json.Unmarshal(encoded, &saved); err != nil {
				t.Fatal(err)
			}
		}
	}
	if saved.SHA256 != hash || saved.Path != path {
		t.Fatalf("saved=%+v hash=%s", saved, hash)
	}
	// The summary result and save arguments must be byte-for-byte equal.
	var summary string
	var saveContent string
	for _, event := range result.Trace {
		if event.Stage == "mcp/tools/call" && event.Tool == pipeline.SummarizeToolName {
			encoded, _ := json.Marshal(event.Result)
			var out pipeline.SummarizeOutput
			_ = json.Unmarshal(encoded, &out)
			summary = out.Summary
		}
		if event.Stage == "model/tool_call" && event.Tool == pipeline.SaveToolName {
			saveContent, _ = event.Arguments["content"].(string)
		}
	}
	if summary == "" || saveContent != summary {
		t.Fatalf("summary transfer changed: %q != %q", saveContent, summary)
	}
}

