	if err != nil || already || cancelled.Status != StatusCancelled || cancelled.NextRunAt != nil {
		t.Fatalf("CancelSchedule() = %+v, %v, %v", cancelled, already, err)
	}
	_, already, err = s.CancelSchedule(ctx, created.ID, now.Add(2*time.Second))
