func TestSchedulerRecordsAPIErrorTimeoutAndStops(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 27, 10, 0, 0, 0, time.UTC)
	db := testStore(t)
	created := schedule(t, db, now, nil)
	rates := &fakeRates{fn: func(context.Context, string, string) (frankfurter.Rate, error) {
		return frankfurter.Rate{}, errors.New("API down")
	}}
	runner := New(db, rates)
	runner.Clock = &fakeClock{now: now}
	if err := runner.RunOnce(ctx); err != nil {
		t.Fatal(err)
	}
	after, _ := db.GetSchedule(ctx, created.ID)
	if after.ErrorCount != 1 || after.LastError == "" {
		t.Fatalf("after=%+v", after)
	}

	created = schedule(t, db, now, nil)
	blocking := &fakeRates{fn: func(ctx context.Context, _, _ string) (frankfurter.Rate, error) {
		<-ctx.Done()
		return frankfurter.Rate{}, ctx.Err()
	}}
	runner = New(db, blocking)
	runner.Clock = &fakeClock{now: now}
	runner.RunTimeout = time.Millisecond
	if err := runner.RunOnce(ctx); err != nil {
		t.Fatal(err)
	}
	after, _ = db.GetSchedule(ctx, created.ID)
	if after.LastError != context.DeadlineExceeded.Error() {
		t.Fatalf("timeout=%+v", after)
	}

	stop := New(db, &fakeRates{})
	stop.Clock = &fakeClock{now: now}
	runCtx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() { done <- stop.Run(runCtx) }()
	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(time.Second):
		t.Fatal("scheduler did not stop")
	}
}

func TestAggregationForZeroOneAndSeveralSnapshots(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 27, 10, 0, 0, 0, time.UTC)
	s, _ := openTestStore(t)
	schedule := createSchedule(t, s, now, nil)
	empty, err := s.Summary(ctx, schedule.ID)
	if err != nil || !empty.InsufficientData || empty.CurrentRate != "" {
		t.Fatalf("empty=%+v %v", empty, err)
	}
	run1, _ := s.ClaimDue(ctx, schedule.ID, now)
	if err := s.CompleteSuccess(ctx, *run1, snapshot("0.8000", "2026-09-26", now), now.Add(time.Second)); err != nil {
		t.Fatal(err)
	}
	one, err := s.Summary(ctx, schedule.ID)
	if err != nil || !one.InsufficientData || one.AbsoluteChange != "0" {
		t.Fatalf("one=%+v %v", one, err)
	}
	run2, _ := s.ClaimDue(ctx, schedule.ID, now.Add(time.Minute))
	_ = s.CompleteFailure(ctx, *run2, errors.New("upstream unavailable"), now.Add(time.Minute+time.Second))
	run3, _ := s.ClaimDue(ctx, schedule.ID, now.Add(2*time.Minute))
	_ = s.CompleteSuccess(ctx, *run3, snapshot("1.0000", "2026-09-27", now.Add(2*time.Minute)), now.Add(2*time.Minute+time.Second))
	many, err := s.Summary(ctx, schedule.ID)
	if err != nil {
		t.Fatal(err)
	}
	if many.CurrentRate != "1.0000" || many.FirstRate != "0.8000" || many.AbsoluteChange != "0.2" || many.PercentChange != "25" || many.MinimumRate != "0.8" || many.MaximumRate != "1" {
		t.Fatalf("summary=%+v", many)
	}
	if many.Schedule.RunCount != 3 || many.Schedule.SuccessCount != 2 || many.Schedule.ErrorCount != 1 || many.Schedule.SnapshotCount != 2 {
		t.Fatalf("counts=%+v", many.Schedule)
	}
}

func updateScheduleAfterRun(ctx context.Context, tx *sql.Tx, id string, success bool, message string, finished time.Time) error {
	successInc, errorInc := 0, 1
	if success {
		successInc, errorInc = 1, 0
	}
	_, err := tx.ExecContext(ctx, `UPDATE schedules SET
 run_count=run_count+1,success_count=success_count+?,error_count=error_count+?,last_run_at=?,last_error=?,
 status=CASE WHEN status='cancelled' THEN 'cancelled' WHEN max_runs IS NOT NULL AND run_count+1>=max_runs THEN 'completed' ELSE status END,
 next_run_at=CASE WHEN status='cancelled' OR (max_runs IS NOT NULL AND run_count+1>=max_runs) THEN NULL ELSE next_run_at END,
 updated_at=? WHERE id=?`, successInc, errorInc, formatTime(finished), nullableString(message), formatTime(finished), id)
	return err
}

