## Результат

Полный цикл выглядит так:

1. агент подключается к MCP по Streamable HTTP;
2. `tools/list` возвращает `get_github_repository` и JSON Schema;
3. схема без изменений передаётся DeepSeek как function tool;
4. запрос к модели использует `tool_choice: auto`;
5. модель формирует `owner` и `repository`;
6. агент выполняет MCP `tools/call`;
7. MCP-сервер вызывает `GET /repos/{owner}/{repository}`;
8. GitHub metadata возвращается как `structuredContent`;
9. агент добавляет результат в историю как `role=tool` с исходным
   `tool_call_id`;
10. следующий sampling-вызов формирует финальный ответ.

В коде нет поиска ключевых слов, регулярных выражений для определения намерения,
принудительного tool call или прямого обращения агента к GitHub в обход MCP.

Фактическая трассировка: [artifacts/local-real-model-smoke.json](artifacts/local-real-model-smoke.json).
Удалённая трассировка: [artifacts/remote-real-model-smoke.json](artifacts/remote-real-model-smoke.json).
Проверка контейнеров: [artifacts/local-container-verification.txt](artifacts/local-container-verification.txt).

func TestMCPToolCallsReturnStructuredResultsAndIdempotentCancel(t *testing.T) {
	session, _ := testSession(t)
	created, err := session.CallTool(context.Background(), ScheduleToolName, map[string]any{
		"owner": "modelcontextprotocol", "repository": "go-sdk", "interval_seconds": 60, "max_runs": 2,
	})
	if err != nil || created.IsError || created.Structured == nil {
		t.Fatalf("schedule result = %+v, %v", created, err)
	}
	var schedule ScheduleOutput
	decodeStructured(t, created.Structured, &schedule)
	if !schedule.OK || schedule.ScheduleID == "" || schedule.Status != store.StatusActive || schedule.NextRunAt == nil {
		t.Fatalf("schedule = %+v", schedule)
	}

	listed, err := session.CallTool(context.Background(), ListToolName, map[string]any{"status": "active"})
	if err != nil || listed.IsError {
		t.Fatalf("list result = %+v, %v", listed, err)
	}
	var list ListOutput
	decodeStructured(t, listed.Structured, &list)
	if !list.OK || list.Count != 1 || list.Monitors[0].ID != schedule.ScheduleID {
		t.Fatalf("list = %+v", list)
	}

	summarized, err := session.CallTool(context.Background(), SummaryToolName, map[string]any{"schedule_id": schedule.ScheduleID})
	if err != nil || summarized.IsError {
		t.Fatalf("summary result = %+v, %v", summarized, err)
	}
	var summary SummaryOutput
	decodeStructured(t, summarized.Structured, &summary)
	if !summary.OK || summary.SnapshotCount != 0 || !summary.InsufficientData {
		t.Fatalf("summary = %+v", summary)
	}

	for i := range 2 {
		cancelled, err := session.CallTool(context.Background(), CancelToolName, map[string]any{"schedule_id": schedule.ScheduleID})
		if err != nil || cancelled.IsError {
			t.Fatalf("cancel %d = %+v, %v", i, cancelled, err)
		}
		var output CancelOutput
		decodeStructured(t, cancelled.Structured, &output)
		if !output.OK || output.Status != store.StatusCancelled || output.AlreadyCancelled != (i == 1) {
			t.Fatalf("cancel %d = %+v", i, output)
		}
	}
}

func TestAgentToolCallLoopReturnsModelAnswerBasedOnMCPResult(t *testing.T) {
	llm := &fakeLLM{responses: []ChatResponse{
		{Choices: []Choice{{FinishReason: "tool_calls", Message: Message{ToolCalls: []ToolCall{{
			ID: "call-1", Type: "function", Function: ToolCallFunction{Name: "get_github_repository", Arguments: `{"owner":"modelcontextprotocol","repository":"go-sdk"}`},
		}}}}}},
		{Choices: []Choice{{FinishReason: "stop", Message: Message{Content: "modelcontextprotocol/go-sdk написан на Go и имеет 5153 звезды."}}}},
	}}
	session := &fakeSession{}
	chatAgent := New(Config{Model: "fake-model"}, llm, fakeConnector{session: session})

	result, err := chatAgent.Ask(context.Background(), "Расскажи об актуальном состоянии репозитория modelcontextprotocol/go-sdk")
	if err != nil {
		t.Fatalf("Ask() error = %v", err)
	}
	if session.name != "get_github_repository" || session.arguments["owner"] != "modelcontextprotocol" || session.arguments["repository"] != "go-sdk" {
		t.Fatalf("tool call = %q %#v", session.name, session.arguments)
	}
	if len(llm.requests) != 2 {
		t.Fatalf("LLM request count = %d", len(llm.requests))
	}
	second := llm.requests[1]
	toolMessage := second.Messages[len(second.Messages)-1]
	if len(second.Messages) < 4 || toolMessage.Role != "tool" || toolMessage.ToolCallID != "call-1" || !strings.Contains(toolMessage.Content, "5153") || !strings.Contains(toolMessage.Content, "GitHub REST API") {
		t.Fatalf("tool result was not sent to model: %+v", second.Messages)
	}
	if llm.requests[0].ToolChoice != "auto" || len(llm.requests[0].Tools) != 1 || llm.requests[0].Tools[0].Function.Name != "get_github_repository" {
		t.Fatalf("first model request does not contain MCP tool with auto choice: %+v", llm.requests[0])
	}
	if !strings.Contains(result.Content, "5153") {
		t.Fatalf("final answer does not use tool result: %q", result.Content)
	}
	if len(result.Trace) != 4 || result.Trace[1].Stage != "model/tool_call" || result.Trace[2].Stage != "mcp/tools/call" {
		t.Fatalf("unexpected trace: %+v", result.Trace)
	}
	if result.Trace[0].Result == nil {
		t.Fatal("tools/list trace does not include schemas")
	}
}

# Day 16 — MCP connection and tools/list

Минимальный MCP-проект на официальном Go SDK:

- `cmd/server` поднимает Streamable HTTP MCP endpoint `/mcp`;
- сервер регистрирует инструмент `server_status`;
- `cmd/client` устанавливает MCP-соединение и получает полный список tools;
- интеграционный тест проверяет handshake, версию протокола и схему tool;
- Docker-контейнер запущен на VPS и доступен только через SSH-туннель.

