func TestRecoveryAndMaxRuns(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 27, 10, 0, 0, 0, time.UTC)
	maxRuns := int64(1)
	s, _ := openTestStore(t)
	schedule := createSchedule(t, s, now, &maxRuns)
	run, err := s.ClaimDue(ctx, schedule.ID, now)
	if err != nil || run == nil {
		t.Fatalf("claim=%+v %v", run, err)
	}
	count, err := s.RecoverInterrupted(ctx, now.Add(time.Second))
	if err != nil || count != 1 {
		t.Fatalf("recover=%d %v", count, err)
	}
	completed, _ := s.GetSchedule(ctx, schedule.ID)
	if completed.Status != StatusCompleted || completed.RunCount != 1 || completed.ErrorCount != 1 || completed.NextRunAt != nil {
		t.Fatalf("completed=%+v", completed)
	}
}

func (s *Store) RecoverInterrupted(ctx context.Context, now time.Time) (int, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT id,schedule_id,scheduled_for FROM runs WHERE status='running' ORDER BY id`)
	if err != nil {
		return 0, err
	}
	var runs []ClaimedRun
	for rows.Next() {
		var run ClaimedRun
		var scheduled string
		if err := rows.Scan(&run.RunID, &run.Schedule.ID, &scheduled); err != nil {
			rows.Close()
			return 0, err
		}
		run.ScheduledFor, err = parseTime(scheduled)
		if err != nil {
			rows.Close()
			return 0, err
		}
		runs = append(runs, run)
	}
	rows.Close()
	for _, run := range runs {
		if err := s.CompleteFailure(ctx, run, errors.New("service restarted during scheduled run"), now); err != nil {
			return 0, err
		}
	}
	return len(runs), nil
}

