d:#242b37;color:var(--ink);border:1px solid #384355;font-size:12px;padding:7px 10px}button:disabled{opacity:.45;cursor:wait}textarea{width:100%;min-height:112px;resize:vertical;border:1px solid #3a4556;border-radius:12px;background:var(--panel2);color:var(--ink);padding:13px;font:inherit;outline:none}textarea:focus{border-color:var(--cyan)}.send{width:100%;margin-top:9px}.dialog,.trace{display:grid;gap:8px;max-height:475px;overflow:auto}.dialog{min-height:142px;margin-top:16px;padding:11px;background:var(--panel2);border-radius:12px}.bubble{padding:10px 12px;border-radius:11px;white-space:pre-wrap;max-width:94%}.user{justify-self:end;background:#243543}.assistant{justify-self:start;background:#28271f}.event{border:1px solid #303a49;border-left:3px solid var(--cyan);border-radius:10px;padding:10px;background:var(--panel2)}.event strong{font:800 11px monospace;color:var(--cyan)}.event.done{border-left-color:var(--green)}pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:7px 0 0;color:#bdc6d3;font:11px/1.45 monospace}.files{grid-column:1/-1}.file-grid{display:grid;grid-template-columns:340px 1fr;gap:14px}.file-list{display:grid;gap:7px;align-content:start}.file{width:100%;text-align:left;background:#202734;color:var(--ink);border:1px solid var(--line)}.file small{display:block;color:var(--muted);font-weight:400}.preview{min-height:180px;max-height:460px;overflow:auto;background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px;white-space:pre-wrap;font:13px/1.55 monospace}.empty,.muted{color:var(--muted)}.error{color:var(--red)}@media(max-width:900px){.hero{display:block}.badge{display:inline-block;margin-top:14px}.grid,.file-grid{grid-template-columns:1fr}.files{grid-column:auto}}
</style></head><body><main>
<section class="hero"><div><div class="kicker">Day 20 · multi-server orchestration</div><h1>MCP Control Room</h1><p>DeepSeek сам выбирает инструменты трёх независимых MCP‑серверов. Trace показывает владельца, tool_call_id, аргументы, structured result и точные переходы данных.</p></div><div class="badge">● 3 MCP servers · tool_choice: auto</div></section>
<section class="pipeline"><div class="step"><b>Knowledge MCP</b><span>search → summarize</span></div><div class="step"><b>GitHub MCP</b><span>repository → release</span></div><div class="step"><b>Artifact MCP</b><span>build → saved Markdown</span></div></section>
<section class="grid"><div class="card"><div class="head"><h2>Естественный запрос</h2><small>DeepSeek выбирает tools</small></div><div class="examples"><button class="example" data-prompt="Исследуй Model Context Protocol по Wikipedia, подготовь краткую сводку, проверь репозиторий modelcontextprotocol/go-sdk и его последний релиз, собери единый технический отчёт и сохрани его в файл mcp-go-sdk-report.md.">Полный flow</button><button class="example" data-prompt="Покажи сведения о репозитории modelcontextprotocol/go-sdk.">GitHub</button><button class="example" data-prompt="Найди по Wikipedia информацию о Model Context Protocol и кратко изложи её.">Wikipedia</button><button class="example" data-prompt="Покажи список сохранённых Markdown-файлов.">Файлы</button></div><textarea id="message">Исследуй Model Context Protocol по Wikipedia, подготовь краткую сводку, проверь репозиторий modelcontextprotocol/go-sdk и его последний релиз, собери единый технический отчёт и сохрани его в файл mcp-go-sdk-report.md.</textarea><button id="send" class="send">Запустить агента</button><div class="head" style="margin-top:19px"><h2>История диалога</h2><button id="reset" class="reset">Новый диалог</button></div><div id="dialog" class="dialog"><div class="empty">История появится здесь.</div></div></div>
<div class="card"><div class="head"><h2>MCP trace</h2><small id="sequence">Ожидается запуск</small></div><div id="trace" class="trace"><div class="empty">Здесь будут аргументы и результаты каждого шага.</div></div></div>
<div class="card files"><div class="head"><h2>Сохранённые Markdown‑файлы</h2><small id="file-count">0 файлов</small></div><div class="file-grid"><div id="files" class="file-list"><div class="empty">Загрузка…</div></div><div id="preview" class="preview muted">Выберите файл, чтобы безопасно открыть его содержимое.</div></div></div></section>
</main><script>
const $=s=>document.querySelector(s),message=$('#message'),send=$('#send'),dialog=$('#dialog'),trace=$('#trace'),files=$('#files'),preview=$('#preview');document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>message.value=b.dataset.prompt);
function bubble(role,text,extra=''){if(dialog.querySelector('.empty'))dialog.innerHTML='';const e=document.createElement('div');e.className='bubble '+role+' '+extra;e.textContent=text;dialog.append(e);dialog.scrollTop=dialog.scrollHeight;return e}
async function history(){try{const r=await fetch('/api/chat/history'),d=await r.json();dialog.innerHTML='';(d.messages||[]).forEach(m=>bubble(m.role,m.content));if(!d.messages?.length)dialog.innerHTML='<div class="empty">История появится здесь.</div>'}catch{dialog.innerHTML='<div class="error">Не удалось загрузить историю.</div>'}}
function renderTrace(items){trace.innerHTML='';const order=[];for(const x of items||[]){const e=document.createElement('div');e.className='event '+(x.stage==='mcp/tools/call'?'done':'');const title=document.createElement('strong');title.textContent=x.stage+(x.mcp_server?' · '+x.mcp_server:'')+(x.tool?' · '+x.tool:'')+(x.tool_call_id?' · '+x.tool_call_id:'');e.append(title);const note=document.createElement('div');note.textContent=x.message+(x.transition?' · '+x.transition:'');e.append(note);const detail=x.arguments??x.result;if(detail!==undefined){const p=document.createElement('pre');p.textContent=JSON.stringify(detail,null,2);e.append(p)}trace.append(e);if(x.stage==='model/tool_call')order.push(x.tool)}$('#sequence').textContent=order.length?order.join(' → '):'Нет tool calls'}
async function refreshFiles(){try{const r=await fetch('/api/files'),d=await r.json();files.innerHTML='';$('#file-count').textContent=(d.files||[]).length+' файлов';if(!d.files?.length){files.innerHTML='<div class="empty">Файлов пока нет.</div>';return}for(const f of d.files){const b=document.createElement('button');b.className='file';const name=document.createElement('span');name.textContent=f.name;const meta=document.createElement('small');meta.textContent=f.bytes+' байт · '+new Date(f.modified_at).toLocaleString('ru-RU');b.append(name,meta);b.onclick=()=>openFile(f.name);files.append(b)}}catch(e){files.innerHTML='<div class="error">'+e.message+'</div>'}}
async function openFile(name){preview.className='preview muted';preview.textContent='Загрузка…';try{const r=await fetch('/api/files/'+encodeURIComponent(name)),d=await r.json();if(!r.ok)throw new Error(d.error);preview.className='preview';preview.textContent=d.content}catch(e){preview.className='preview error';preview.textContent=e.message}}
send.onclick=async()=>{const prompt=message.value.trim();if(!prompt)return;send.disabled=true;bubble('user',prompt);const wait=bubble('assistant','Агент выбирает маршрут между Knowledge, GitHub и Artifact MCP…','muted');trace.innerHTML='<div class="empty">DeepSeek получает объединённый tools/list и выбирает первый шаг…</div>';try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:prompt})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Ошибка запроса');wait.className='bubble assistant';wait.textContent=d.content;renderTrace(d.trace);await refreshFiles()}catch(e){wait.className='bubble assistant error';wait.textContent=e.message}finally{send.disabled=false}}
$('#reset').onclick=async()=>{await fetch('/api/chat/session',{method:'DELETE'});dialog.innerHTML='<div class="empty">Начат новый диалог.</div>';trace.innerHTML='<div class="empty">Здесь будут аргументы и результаты каждого шага.</div>';$('#sequence').textContent='Ожидается запуск'};history();refreshFiles();
</script></body></html>`

