func TestRecoveryAndMaxRuns(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 27, 10, 0, 0, 0, time.UTC)
	maxRuns := int64(1)
	s, _ := openTestStore(t)
	schedule := createSchedule(t, s, now, &maxRuns)
	run, err := s.ClaimDue(ctx, schedule.ID, now)
	if err != nil || run == nil {
		t.Fatalf("claim=%+v %v", run, err)
	}
	count, err := s.RecoverInterrupted(ctx, now.Add(time.Second))
	if err != nil || count != 1 {
		t.Fatalf("recover=%d %v", count, err)
	}
	completed, _ := s.GetSchedule(ctx, schedule.ID)
	if completed.Status != StatusCompleted || completed.RunCount != 1 || completed.ErrorCount != 1 || completed.NextRunAt != nil {
		t.Fatalf("completed=%+v", completed)
	}
}

func TestRunOnceRecoversOverdueScheduleWithoutRapidCatchupAndHonorsMaxRuns(t *testing.T) {
	ctx := context.Background()
	start := time.Date(2026, 9, 26, 10, 0, 0, 0, time.UTC)
	maxRuns := int64(2)
	s := schedulerStore(t)
	created := scheduleAt(t, s, start, &maxRuns)
	clock := &fakeClock{now: start.Add(10 * time.Minute)}
	github := &fakeGitHub{}
	planner := New(s, github)
	planner.Clock = clock
	if err := planner.RunOnce(ctx); err != nil {
		t.Fatal(err)
	}
	afterFirst, _ := s.GetSchedule(ctx, created.ID)
	if afterFirst.NextRunAt == nil || !afterFirst.NextRunAt.Equal(start.Add(11*time.Minute)) || github.calls.Load() != 1 {
		t.Fatalf("overdue next run = %+v, calls=%d", afterFirst, github.calls.Load())
	}
	clock.Set(start.Add(11 * time.Minute))
	if err := planner.RunOnce(ctx); err != nil {
		t.Fatal(err)
	}
	completed, _ := s.GetSchedule(ctx, created.ID)
	if completed.Status != store.StatusCompleted || completed.NextRunAt != nil || completed.RunCount != 2 {
		t.Fatalf("max-runs schedule = %+v", completed)
	}
}

func TestCRUDPersistenceAndSQLiteConfiguration(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 27, 10, 0, 0, 0, time.UTC)
	s, path := openTestStore(t)
	created := createSchedule(t, s, now, nil)
	if created.Status != StatusActive || created.NextRunAt == nil || !created.NextRunAt.Equal(now) {
		t.Fatalf("created=%+v", created)
	}
	items, err := s.ListSchedules(ctx, StatusActive)
	if err != nil || len(items) != 1 {
		t.Fatalf("list=%+v %v", items, err)
	}
	cancelled, already, err := s.CancelSchedule(ctx, created.ID, now.Add(time.Second))
	if err != nil || already || cancelled.Status != StatusCancelled {
		t.Fatalf("cancel=%+v %v %v", cancelled, already, err)
	}
	_, already, err = s.CancelSchedule(ctx, created.ID, now.Add(2*time.Second))
	if err != nil || !already {
		t.Fatalf("idempotent cancel=%v %v", already, err)
	}
	_ = s.Close()
	reopened, err := Open(ctx, path)
	if err != nil {
		t.Fatal(err)
	}
	defer reopened.Close()
	persisted, err := reopened.GetSchedule(ctx, created.ID)
	if err != nil || persisted.Status != StatusCancelled {
		t.Fatalf("persisted=%+v %v", persisted, err)
	}
	var foreignKeys int
	_ = reopened.db.QueryRow(`PRAGMA foreign_keys`).Scan(&foreignKeys)
	var journal string
	_ = reopened.db.QueryRow(`PRAGMA journal_mode`).Scan(&journal)
	if foreignKeys != 1 || journal != "wal" {
		t.Fatalf("foreign_keys=%d journal=%s", foreignKeys, journal)
	}
}

func TestStoreMigrationsCreateListCancelAndPersist(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 26, 10, 0, 0, 0, time.UTC)
	s, path := openTestStore(t)
	created := createTestSchedule(t, s, now, nil)
	if created.ID == "" || created.Status != StatusActive || created.NextRunAt == nil || !created.NextRunAt.Equal(now) {
		t.Fatalf("created schedule = %+v", created)
	}
	loaded, err := s.GetSchedule(ctx, created.ID)
	if err != nil || loaded.Repository != "go-sdk" {
		t.Fatalf("GetSchedule() = %+v, %v", loaded, err)
	}
	items, err := s.ListSchedules(ctx, StatusActive)
	if err != nil || len(items) != 1 || items[0].ID != created.ID {
		t.Fatalf("ListSchedules() = %+v, %v", items, err)
	}
	cancelled, already, err := s.CancelSchedule(ctx, created.ID, now.Add(time.Second))
	if err != nil || already || cancelled.Status != StatusCancelled || cancelled.NextRunAt != nil {
		t.Fatalf("CancelSchedule() = %+v, %v, %v", cancelled, already, err)
	}
	_, already, err = s.CancelSchedule(ctx, created.ID, now.Add(2*time.Second))
	if err != nil || !already {
		t.Fatalf("second CancelSchedule() already=%v err=%v", already, err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	reopened, err := Open(ctx, path)
	if err != nil {
		t.Fatalf("reopen/migrate error = %v", err)
	}
	defer reopened.Close()
	persisted, err := reopened.GetSchedule(ctx, created.ID)
	if err != nil || persisted.Status != StatusCancelled {
		t.Fatalf("persisted schedule = %+v, %v", persisted, err)
	}
	var foreignKeys int
	if err := reopened.db.QueryRow(`PRAGMA foreign_keys`).Scan(&foreignKeys); err != nil || foreignKeys != 1 {
		t.Fatalf("foreign_keys = %d, %v", foreignKeys, err)
	}
	var journal string
	if err := reopened.db.QueryRow(`PRAGMA journal_mode`).Scan(&journal); err != nil || journal != "wal" {
		t.Fatalf("journal_mode = %q, %v", journal, err)
	}
}

